}

//wgl2
p5.RendererGL.prototype._initContext = function() {// hack thx to github.com/diwi/p5.EasyCam/blob/master/examples/ReactionDiffusion_Webgl2/ReactionDiffusion_Webgl2.js#L563
  this.drawingContext = this.canvas.getContext('webgl2',this._pInst._glAttributes);
	if (this.drawingContext===null)
		alert('couldnt webgl2');
};
function setup() {
  pixelDensity(1);
  createCanvas(windowWidth, windowHeight, WEBGL);
	noStroke()


	//disable right click
	document.addEventListener('contextmenu', event => event.preventDefault());
}

var theta=0
var phi= 3.14/4
function draw() {
  shader(theShader);

  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_time", millis() / 1000.0);

	map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0,  height , -1, 1)
	map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0,  height,  1,-1)
	//N= (sin(millis()/1000.0*2.)+1.5)*64.;
	N= 40
	theShader.setUniform("N",N);

	theShader.setUniform("MODE", mouseButton==RIGHT);

	//this camera is actually good
	if(((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))){
		theta= (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/width*PI*2
		phi= -(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/height*PI*.6 + PI/8.
	}
	else{
		theta-= .001
	}

	rotateY(-theta);
	rotateX(phi);

	plane(1,1);
}

